const dialog=document.querySelector('dialog');let lastTrigger;
document.querySelectorAll('[data-project]').forEach(button=>button.addEventListener('click',()=>{lastTrigger=button;const p=projects[button.dataset.project];document.querySelector('#dialog-label').textContent=p.label;document.querySelector('#dialog-title').textContent=p.title;document.querySelector('#dialog-description').textContent=p.description;document.querySelector('#dialog-tags').replaceChildren(...p.tags.map(t=>{const s=document.createElement('span');s.textContent=t;return s}));const details=document.querySelector('#dialog-details');details.replaceChildren();const h=document.createElement('h3');h.textContent=p.heading||'The build direction';details.append(h);const ul=document.createElement('ul');p.details.forEach(t=>{const li=document.createElement('li');li.textContent=t;ul.append(li)});details.append(ul);if(p.note){const note=document.createElement('p');note.textContent=p.note;details.append(note)}const links=p.links||[['Explore the source inspiration ↗','https://github.com/blendi-remade/dioramas']];document.querySelector('#dialog-links').replaceChildren(...links.map(([title,url])=>{const a=document.createElement('a');a.textContent=title;a.href=url;a.target='_blank';a.rel='noopener';return a}));dialog.showModal();document.body.style.overflow='hidden'}));
document.querySelector('#close-dialog').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});dialog.addEventListener('close',()=>{document.body.style.overflow='';lastTrigger?.focus()});
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-filter]').forEach(x=>{const active=x===b;x.classList.toggle('active',active);x.setAttribute('aria-pressed',String(active))});document.querySelectorAll('[data-category]').forEach(c=>c.hidden=b.dataset.filter!=='all'&&c.dataset.category!==b.dataset.filter)});
document.querySelector('#copy-email').onclick=async()=>{const status=document.querySelector('#copy-status');try{await navigator.clipboard.writeText('shivansh15nayak@gmail.com');status.textContent='Email copied.'}catch{status.textContent='Email: shivansh15nayak@gmail.com'}setTimeout(()=>status.textContent='',5000)};document.querySelector('#year').textContent=new Date().getFullYear();
// Original Canvas orbital sculpture. No third-party scene or model assets.
const canvas=document.querySelector('#sculpture'),ctx=canvas.getContext('2d');const reduced=matchMedia('(prefers-reduced-motion: reduce)');let paused=reduced.matches,visible=true,width=0,height=0,angle=.2,px=0,py=0;const motion=document.querySelector('#motion');function updateMotion(){motion.textContent=paused?'▶':'Ⅱ';motion.setAttribute('aria-label',paused?'Play sculpture animation':'Pause sculpture animation')}updateMotion();motion.onclick=()=>{paused=!paused;updateMotion()};reduced.addEventListener('change',e=>{paused=e.matches;updateMotion()});function resize(){width=canvas.clientWidth;height=canvas.clientHeight;const dpr=Math.min(devicePixelRatio||1,2);canvas.width=width*dpr;canvas.height=height*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)}new ResizeObserver(resize).observe(canvas);canvas.addEventListener('pointermove',e=>{const r=canvas.getBoundingClientRect();px=((e.clientX-r.left)/r.width-.5)*.5;py=((e.clientY-r.top)/r.height-.5)*.3});canvas.addEventListener('pointerleave',()=>{px=py=0});new IntersectionObserver(entries=>visible=entries[0].isIntersecting).observe(canvas);document.addEventListener('visibilitychange',()=>visible=!document.hidden);
function project(x,y,z,rotation){let yy=y*Math.cos(rotation)-z*Math.sin(rotation),zz=y*Math.sin(rotation)+z*Math.cos(rotation);let xx=x*Math.cos(.55+px)+zz*Math.sin(.55+px);zz=-x*Math.sin(.55+px)+zz*Math.cos(.55+px);const k=620/(620+zz);return [width*.56+xx*k,height*.49+(yy+py*70)*k,zz,k]}
function draw(){if(width&&visible){if(!paused)angle+=.003;ctx.clearRect(0,0,width,height);const radius=Math.min(width*.28,height*.34),rotation=angle*.4+.65;let glow=ctx.createRadialGradient(width*.56,height*.5,0,width*.56,height*.5,radius*1.8);glow.addColorStop(0,'#b0ff5d12');glow.addColorStop(1,'#b0ff5d00');ctx.fillStyle=glow;ctx.fillRect(0,0,width,height);const lines=[];for(let ring=0;ring<30;ring++){let points=[];const alpha=ring/30*Math.PI*2;for(let i=0;i<=140;i++){const t=i/140*Math.PI*2;const r=radius*(.72+.27*Math.cos(t));const x=r*Math.cos(alpha),y=r*Math.sin(alpha),z=radius*.39*Math.sin(t);points.push(project(x,y,z,rotation))}lines.push({points,z:points.reduce((a,p)=>a+p[2],0)/points.length,ring})}lines.sort((a,b)=>b.z-a.z);for(const line of lines){const bright=Math.max(0,Math.min(1,(radius-line.z)/(radius*2)));ctx.strokeStyle=`rgba(${Math.round(135+100*bright)},${Math.round(158+90*bright)},${Math.round(101+73*bright)},${.17+bright*.68})`;ctx.lineWidth=.7+bright*.65;ctx.beginPath();line.points.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1]));ctx.stroke()}for(let band=0;band<22;band++){const t=band/22*Math.PI*2;ctx.beginPath();for(let i=0;i<=140;i++){const a=i/140*Math.PI*2;const r=radius*(.72+.27*Math.cos(t));const p=project(r*Math.cos(a),r*Math.sin(a),radius*.39*Math.sin(t),rotation);i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1])}ctx.strokeStyle='#b9e77b30';ctx.lineWidth=.6;ctx.stroke()}ctx.fillStyle='#d7e4bb55';for(let i=0;i<28;i++){const a=i*2.399;const r=radius*(1.2+(i%4)*.15);ctx.beginPath();ctx.arc(width*.56+Math.cos(a+angle*.1)*r,height*.49+Math.sin(a+angle*.1)*r*.8,i%3===0?1.2:.6,0,Math.PI*2);ctx.fill()}}requestAnimationFrame(draw)}resize();draw();
